//! Prints the IR as Rust source. Plain integer and string tables only, so compile time and
//! binary size stay small and predictable.

use super::{Ir, NsRow};
use std::fmt::Write;

fn header(ir: &Ir, what: &str) -> String {
    format!(
        "// @generated by `cargo xtask codegen` (xtask/src/codegen). Do not edit by hand.\n\
         // Input: dotnet/Open-XML-SDK@{} data/ (MIT), manifest sha256 {}\n\
         // {what}\n\n",
        &ir.commit.get(..8).unwrap_or(&ir.commit),
        ir.digest
    )
}

fn lit(s: &str) -> String {
    format!("{s:?}")
}

fn wrap(items: &[String]) -> String {
    let mut out = String::new();
    let mut line = String::from("   ");
    for it in items {
        if line.len() + it.len() + 2 > 100 {
            out.push_str(&line);
            out.push('\n');
            line = String::from("   ");
        }
        let _ = write!(line, " {it},");
    }
    out.push_str(&line);
    out.push('\n');
    out
}

fn table<T>(out: &mut String, name: &str, ty: &str, rows: &[T], f: impl Fn(&T) -> String) {
    let items: Vec<String> = rows.iter().map(f).collect();
    let _ = writeln!(out, "pub(crate) static {name}: [{ty}; {}] = [", rows.len());
    out.push_str(&wrap(&items));
    out.push_str("];\n\n");
}

pub fn files(ir: &Ir) -> Vec<(String, String)> {
    vec![
        ("mod.rs".into(), mod_rs(ir)),
        ("names.rs".into(), names(ir)),
        ("models.rs".into(), models(ir)),
        ("attrs.rs".into(), attrs(ir)),
        ("parts.rs".into(), parts(ir)),
    ]
}

fn mod_rs(ir: &Ir) -> String {
    let mut s = header(
        ir,
        "Generated schema tables for the WordprocessingML parts stetdoc edits.",
    );
    for sup in &ir.supplements {
        let _ = writeln!(s, "// supplement: {sup}");
    }
    s.push('\n');
    s.push_str(
        "// Layout and meaning of every table: `schema/tables.rs`.\n\n\
         #[rustfmt::skip]\npub(crate) mod attrs;\n\
         #[rustfmt::skip]\npub(crate) mod models;\n\
         #[rustfmt::skip]\npub(crate) mod names;\n\
         #[rustfmt::skip]\npub(crate) mod parts;\n",
    );
    s
}

fn ns_row(n: &NsRow) -> String {
    format!(
        "({}, {}, {}, {})",
        lit(&n.uri),
        lit(&n.prefix),
        n.ext,
        n.understood
    )
}

fn names(ir: &Ir) -> String {
    let mut s = header(ir, "Namespaces, names and declarations.");
    s.push_str("use crate::schema::tables::{DeclRow, NsRow};\n\n");
    let _ = writeln!(
        s,
        "pub(crate) static NAMESPACES: [NsRow; {}] = [",
        ir.namespaces.len()
    );
    s.push_str(&wrap(&ir.namespaces.iter().map(ns_row).collect::<Vec<_>>()));
    s.push_str("];\n\n");
    table(
        &mut s,
        "STRICT_ALIASES",
        "(&str, u8)",
        &ir.strict_aliases,
        |(u, i)| format!("({}, {i})", lit(u)),
    );
    table(
        &mut s,
        "PREVIEW_ALIASES",
        "(&str, u8)",
        &ir.preview_aliases,
        |(u, i)| format!("({}, {i})", lit(u)),
    );
    table(&mut s, "NAMES", "(u8, &str)", &ir.names, |(ns, l)| {
        format!("({ns}, {})", lit(l))
    });
    table(&mut s, "DECLS", "DeclRow", &ir.decls, |d| {
        let flags = u8::from(d.leaf_text)
            | (u8::from(d.opaque) << 1)
            | (u8::from(d.canonical) << 2)
            | (u8::from(d.reorderable) << 3);
        format!(
            "({}, {}, {flags}, {}, {})",
            d.name,
            lit(&d.ty),
            d.model,
            d.attrs
        )
    });
    s
}

fn models(ir: &Ir) -> String {
    let mut s = header(
        ir,
        "Content models: one minimal DFA per distinct content model.",
    );
    s.push_str("use crate::schema::tables::ModelRow;\n\n");
    let (mut alpha_name, mut alpha_decl, mut alpha_rank, mut alpha_once, mut trans, mut accept) =
        (vec![], vec![], vec![], vec![], vec![], vec![]);
    let mut rows = Vec::new();
    for m in &ir.models {
        let d = &m.dfa;
        rows.push(format!(
            "({}, {}, {}, {}, {}, {})",
            alpha_name.len(),
            m.alpha_name.len(),
            d.states(),
            trans.len(),
            accept.len(),
            d.any
        ));
        alpha_name.extend(m.alpha_name.iter().map(u16::to_string));
        alpha_decl.extend(m.alpha_decl.iter().map(u16::to_string));
        alpha_rank.extend(d.rank.iter().map(u16::to_string));
        alpha_once.extend(d.once.iter().map(bool::to_string));
        trans.extend(d.trans.iter().map(u16::to_string));
        accept.extend(d.accept.iter().map(|a| u8::from(*a).to_string()));
    }
    let _ = writeln!(
        s,
        "pub(crate) static MODELS: [ModelRow; {}] = [",
        rows.len()
    );
    s.push_str(&wrap(&rows));
    s.push_str("];\n\n");
    for (name, ty, v) in [
        ("ALPHA_NAME", "u16", &alpha_name),
        ("ALPHA_DECL", "u16", &alpha_decl),
        ("ALPHA_RANK", "u16", &alpha_rank),
        ("ALPHA_ONCE", "bool", &alpha_once),
        ("TRANS", "u16", &trans),
        ("ACCEPT", "u8", &accept),
    ] {
        let _ = writeln!(s, "pub(crate) static {name}: [{ty}; {}] = [", v.len());
        s.push_str(&wrap(v));
        s.push_str("];\n\n");
    }
    s
}

fn attrs(ir: &Ir) -> String {
    let mut s = header(ir, "Attribute sets, value specifications and enumerations.");
    // Attribute sets.
    let mut items = Vec::new();
    let mut sets = Vec::new();
    for set in &ir.attr_sets {
        sets.push(format!("({}, {})", items.len(), set.len()));
        for a in set {
            items.push(format!("({}, {}, {})", a.name, a.spec, a.required));
        }
    }
    table(&mut s, "ATTR_SETS", "(u32, u16)", &sets, |x| x.clone());
    table(&mut s, "ATTR_ITEMS", "(u16, u16, bool)", &items, |x| {
        x.clone()
    });

    // Specs -> clauses -> predicates.
    let mut preds: Vec<(u8, i64, i64)> = Vec::new();
    let mut clauses: Vec<Vec<usize>> = Vec::new();
    let mut spec_rows = Vec::new();
    let mut spec_clauses: Vec<usize> = Vec::new();
    for spec in &ir.specs {
        spec_rows.push((spec_clauses.len(), spec.len()));
        for c in spec {
            let ids: Vec<usize> = c
                .iter()
                .map(|p| {
                    let code = p.code();
                    preds.iter().position(|x| *x == code).unwrap_or_else(|| {
                        preds.push(code);
                        preds.len() - 1
                    })
                })
                .collect();
            let cid = clauses.iter().position(|x| *x == ids).unwrap_or_else(|| {
                clauses.push(ids);
                clauses.len() - 1
            });
            spec_clauses.push(cid);
        }
    }
    let mut clause_preds: Vec<usize> = Vec::new();
    let clause_rows: Vec<String> = clauses
        .iter()
        .map(|c| {
            let r = format!("({}, {})", clause_preds.len(), c.len());
            clause_preds.extend(c);
            r
        })
        .collect();
    table(&mut s, "SPECS", "(u32, u16)", &spec_rows, |(a, b)| {
        format!("({a}, {b})")
    });
    table(&mut s, "SPEC_CLAUSES", "u16", &spec_clauses, |x| {
        x.to_string()
    });
    table(&mut s, "CLAUSES", "(u32, u16)", &clause_rows, |x| x.clone());
    table(&mut s, "CLAUSE_PREDS", "u16", &clause_preds, |x| {
        x.to_string()
    });
    table(&mut s, "PREDS", "(u8, i64, i64)", &preds, |(k, a, b)| {
        format!("({k}, {a}, {b})")
    });

    // Enumerations.
    let mut values: Vec<&String> = Vec::new();
    let mut enum_rows = Vec::new();
    for set in &ir.enums {
        enum_rows.push(format!("({}, {})", values.len(), set.len()));
        values.extend(set.iter());
    }
    table(&mut s, "ENUM_SETS", "(u32, u16)", &enum_rows, |x| x.clone());
    table(&mut s, "ENUM_VALUES", "&str", &values, |x| lit(x));
    s
}

fn parts(ir: &Ir) -> String {
    let mut s = header(ir, "Part kinds, their root declarations and content types.");
    s.push_str("/// The WordprocessingML parts the schema covers.\n");
    s.push_str("#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]\npub enum PartKind {\n");
    for p in &ir.parts {
        let _ = writeln!(
            s,
            "    /// The part at `{}` and its siblings of the same kind.",
            p.default_path
        );
        let _ = writeln!(s, "    {},", p.variant);
    }
    s.push_str("}\n\nimpl PartKind {\n    pub(crate) const ALL: [PartKind; ");
    let _ = write!(s, "{}] = [", ir.parts.len());
    s.push_str(
        &ir.parts
            .iter()
            .map(|p| format!("PartKind::{}", p.variant))
            .collect::<Vec<_>>()
            .join(", "),
    );
    s.push_str("];\n}\n\n");
    table(&mut s, "PART_ROOTS", "u16", &ir.parts, |p| {
        p.root.to_string()
    });
    table(&mut s, "PART_REL_TYPES", "&str", &ir.parts, |p| {
        lit(&p.rel_type)
    });
    table(&mut s, "PART_PATHS", "&str", &ir.parts, |p| {
        lit(&p.default_path)
    });
    table(
        &mut s,
        "CONTENT_TYPES",
        "(&str, u8)",
        &ir.content_types,
        |(c, i)| format!("({}, {i})", lit(c)),
    );
    s
}
